function solve(A,b){let n=b.length,M=A.map((r,i)=>[...r,b[i]]);for(let i=0;i<n;i++){let p=i;for(let j=i+1;j<n;j++)if(Math.abs(M[j][i])>Math.abs(M[p][i]))p=j;[M[i],M[p]]=[M[p],M[i]];let q=M[i][i]||1e-10;for(let k=i;k<=n;k++)M[i][k]/=q;for(let j=0;j<n;j++)if(j!==i){q=M[j][i];for(let k=i;k<=n;k++)M[j][k]-=q*M[i][k];}}return M.map(r=>r[n]);}
function fit(rows,feat){const X=rows.map(r=>feat(r.x)),n=X[0].length,A=Array.from({length:n},()=>Array(n).fill(0)),b=Array(n).fill(0);X.forEach((x,i)=>x.forEach((v,j)=>{b[j]+=v*rows[i].y;x.forEach((w,k)=>A[j][k]+=v*w);}));A.forEach((r,j)=>r[j]+=j?0.03:1e-8);return solve(A,b);}
